helpers._collect_nodes:
def _collect_nodes(root): nodes = []; stack = [root] if root else []; 
    while stack: n = stack.pop(); nodes.append(n); 
    if n.right: stack.append(n.right); 
    if n.left: stack.append(n.left); 
    return nodes

helpers._check_parent_relation:
def _check_parent_relation(node, parent): 
    if node.left: 
        if parent[node.left.data] != node.data: return False 
    if node.right: 
        if parent[node.right.data] != node.data: return False 
    return True
